local config = {
  ui_story_31530401_1_dialog_content = "<color=#e8d9bb>1st Legion, Camp Rekrutan Baru</color>",
  ui_story_31530401_2_dialog_content = "Satu, dua, tiga, empat!",
  ui_story_31530401_3_dialog_content = "Satu, dua, tiga—empat!",
  ui_story_31530401_4_dialog_content = "Hosh... Hosh... Kenapa latihan dimulai sebelum fajar...?",
  ui_story_31530401_5_dialog_content = "Akhirnya... lari itu selesai.",
  ui_story_31530401_6_dialog_content = "*Uhuk*... Benar, kan? Kami baru tiba di kamp beberapa jam yang lalu.",
  ui_story_31530401_7_dialog_content = "Apakah kalian masih belum menyadari di mana kita berada? Ini adalah 1st Legion dari Illumina Federation—",
  ui_story_31530401_8_dialog_content = "Konon latihan anggota baru di sini adalah latihan paling keras!",
  ui_story_31530401_9_dialog_content = "Oh, berhenti mengeluh. Saya dengar bahwa latihan 2nd Legion bahkan lebih tidak manusiawi.",
  ui_story_31530401_10_dialog_content = "Omong-omong, kau tahu siapa instruktur kita?",
  ui_story_31530401_11_dialog_content = "Aku.",
  ui_story_31530401_12_dialog_content = "C-Commander Sharona!",
  ui_story_31530401_13_dialog_content = "Jika aku ingat dengan benar, perintah yang disiarkan sebelumnya adalah, \"Semua anggota baru harus berlari dalam formasi sejauh 5 km.\"",
  ui_story_31530401_14_dialog_content = "Berdiri di sekitar sambil mengobrol tidak termasuk dalam perintah tersebut.",
  ui_story_31530401_15_dialog_content = "Apakah ini yang mereka ajarkan kepada kamu untuk dilakukan di sekolah?",
  ui_story_31530401_16_dialog_content = "...",
  ui_story_31530401_17_dialog_content = "Baiklah, anggota baru, dengarkan! Kamu semua bisa mengucapkan terima kasih pada rekan-rekan kalian yang tadi bergosip.",
  ui_story_31530401_18_dialog_content = "Berkat mereka, setiap orang harus melakukan 100 squat lagi!",
  ui_story_31530401_19_dialog_content = "Serius?! Tenagaku sudah habis...",
  ui_story_31530401_20_dialog_content = "Hmm? Prajurit di baris paling belakang, maju berbaris!",
  ui_story_31530401_21_dialog_content = "Uh... Ini barisan paling belakang, bukan?",
  ui_story_31530401_22_dialog_content = "Siap, Kapten! Rekrutan baru di baris paling belakang, siap menunggu perintah Anda!",
  ui_story_31530401_23_dialog_content = "Hmph. Ternyata kalian tahu cara melapor ke atasanmu, ya.",
  ui_story_31530401_24_dialog_content = "Kalian berdua! Push-up 100 kali lebih banyak daripada yang lain!",
  ui_story_31530401_25_dialog_content = "Siap, Kapten!",
  ui_story_31530401_26_dialog_content = "1, 2, 3, 4, 5, 6, 7...",
  ui_story_31530401_27_dialog_content = "Luar biasa...",
  ui_story_31530401_28_dialog_content = "Itu banyak sekali push-up, dan semua tanpa mengeluarkan keringat!",
  ui_story_31530401_29_dialog_content = "(Anggota baru ini... Mengapa dirinya tampak tidak asing?)",
  ui_story_31530401_30_dialog_content = "Lapor, Kapten! 100 push-up sudah selesai, latihan selesai!",
  ui_story_31530401_31_dialog_content = "Bagus! Bilang pada orang di sampingmu untuk bergegas... Tunggu! Grand Marshal Reinhardt?!",
  ui_story_31530401_32_dialog_content = "Apa? Grand Marshal di sini?",
  ui_story_31530401_33_dialog_content = "Benar dia Grand Marshal! Aslinya bahkan jauh lebih mengesankan secara langsung!",
  ui_story_31530401_34_dialog_content = "Tak kusangka aku bisa berlari 5 km bersama Grand Marshal!",
  ui_story_31530401_35_dialog_content = "Lalu, yang di sebelahnya... PlayerName? Mengapa kau juga di sini?",
  ui_story_31530401_36_dialog_content = "Ah, kurasa... aku kemari untuk membantu mencatat.",
  ui_story_31530401_37_dialog_content = "Dan kemudian aku juga tidak tahu apa yang akhirnya terjadi.",
  ui_story_31530401_38_dialog_content = "Aku hanya diam-diam mengikuti Grand Marshal dan berbaur dalam barisan anggota baru...",
  ui_story_31530401_39_dialog_content = "Haha, kamu tidak bisa benar-benar memahaminya tanpa mengalaminya sendiri.",
  ui_story_31530401_40_dialog_content = "Sekarang kamu lebih sadar tentang upaya yang dilakukan setiap prajurit Illumina dalam latihan di belakang layar.",
  ui_story_31530401_41_dialog_content = "Grand Marshal, mohon maaf. Saya tidak diberitahu bahwa Anda akan datang mengamati. Mohon maaf atas ketidaksopanan saya sebelumnya.",
  ui_story_31530401_42_dialog_content = "Commander Sharona, sudah menjadi tugasmu untuk mengawasi kedisiplinan tiap anggota baru.",
  ui_story_31530401_43_dialog_content = "Kamu tidak melakukan kesalahan apa pun, jadi tidak perlu minta maaf.",
  ui_story_31530401_44_dialog_content = "Selama aku berdiri di formasi, aku berkewajiban untuk mendengarkan perintah instruktur latihan.",
  ui_story_31530401_45_dialog_content = "Siap, Kapten!",
  ui_story_31530401_46_dialog_content = "Tapi tentang Navigator...",
  ui_story_31530401_47_dialog_content = "Dia hanya tamu yang datang menemaniku selama inspeksiku, bukan prajurit yang telah menjalani latihan.",
  ui_story_31530401_48_dialog_content = "Lari 5 km lebih dari cukup untuknya.",
  ui_story_31530401_49_dialog_content = "Aku akan menyelesaikan sisa latihannya sebagai gantinya.",
  ui_story_31530401_50_option_content = "Terima kasih, Grand Marshal.",
  ui_story_31530401_51_dialog_content = "Namun, daripada menyelesaikannya untukku, mengapa tidak meminta Sharona untuk mengecualikan aku dari latihan sama sekali?",
  ui_story_31530401_52_dialog_content = "PlayerName, perkataan seorang Illumina Legion Commander tidak boleh dianggap enteng.",
  ui_story_31530401_53_dialog_content = "Belum lagi, latihan sebenarnya adalah sebuah penghargaan bagi para prajurit.",
  ui_story_31530401_54_dialog_content = "Setiap menit latihan meningkatkan kekuatan kita di medan pertempuran.",
  ui_story_31530401_55_dialog_content = "Satu menit tambahan latihan akan meningkatkan sedikit lagi kekuatan.",
  ui_story_31530401_56_dialog_content = "Saya selalu bersedia menerima lebih banyak latihan!",
  ui_story_31530401_57_option_content = "Tak perlu membelaku sampai sejauh itu, Grand Marshal.",
  ui_story_31530401_58_dialog_content = "Aku belum pernah menjalani latihan, tetapi berdiri di sini sekarang...",
  ui_story_31530401_59_dialog_content = "Itu salahku karena berbicara bebas tanpa izin.",
  ui_story_31530401_60_dialog_content = "Aku tidak akan merasa nyaman jika kamu menjalani hukuman di tempatku.",
  ui_story_31530401_61_dialog_content = "Aku akan melakukannya sendiri!",
  ui_story_31530401_62_dialog_content = "Hahaha, baiklah, karena Caelestite yang tidak berpengalaman mengatakannya...",
  ui_story_31530401_63_dialog_content = "Aku tidak bisa hanya berdiri menunggu untuk dikalahkan!",
  ui_story_31530401_64_dialog_content = "PlayerName, aku menerima tantangan latihanmu!",
  ui_story_31530401_65_dialog_content = "Kok malah jadi tantangan...?",
  ui_story_31530401_66_dialog_content = "Bahkan Grand Marshal berlatih sangat keras... A-Aku juga akan ikut!",
  ui_story_31530401_67_dialog_content = "Saya juga ingin meningkatkan kemampuan saya!",
  ui_story_31530401_68_dialog_content = "Instruktur! Kami semua ingin latihan tambahan!",
  ui_story_31530401_69_dialog_content = "(Anggota baru yang tadinya mengeluh kini penuh semangat. Mereka seperti menjelma jadi orang yang berbeda...)",
  ui_story_31530401_70_dialog_content = "(Apakah ini kekuatan pengaruh Reinhardt?)",
  ui_story_31530401_71_dialog_content = "(Tapi aku tak menyangka inspeksi Reinhardt jadi...)",
  ui_story_31530401_72_dialog_content = "(Begitu melelahkan!)",
  ui_story_31530401_73_dialog_content = "PlayerName, hampir fajar. Waktunya menuju ke tempat berhenti kita selanjutnya.",
  ui_story_31530401_74_dialog_content = "<color=#e8d9bb>Gannon City, Research Center</color>",
  ui_story_31530401_75_dialog_content = "Itu adalah hasil dari penelitian kami dalam beberapa hari terakhir. Tentu saja, kami akan terus mengulangi proyek kami di masa depan.",
  ui_story_31530401_76_dialog_content = "(Suatu model mesin game yang tak memiliki konten apa pun, suatu kebun mawar penuh warna, catatan observasi Hiiro...)",
  ui_story_31530401_77_dialog_content = "(Aku bukan pakar, tetapi... apakah ini benar-benar dapat dianggap hasil riset?)",
  ui_story_31530401_78_dialog_content = "Riset ilmiah memerlukan lebih banyak kesabaran dan ketahanan daripada yang dimiliki individu rata-rata.",
  ui_story_31530401_79_dialog_content = "Terkadang juga memerlukan keberuntungan, dan waktu.",
  ui_story_31530401_80_dialog_content = "Aku selalu kagum dengan kolega kami di Illumina Research Center.",
  ui_story_31530401_81_dialog_content = "Saya merasa terhormat telah memiliki kesempatan untuk melihat hasil risetmu hari ini. Itu meninggalkan kesan yang sangat besar pada saya!",
  ui_story_31530401_82_dialog_content = "Mesin game Gronru belum memiliki konten aktual apa pun...",
  ui_story_31530401_83_dialog_content = "Tapi, dugaanku, kau sedang mencoba untuk membuat suatu sistem simulasi pertempuran bagi anggota Illumina untuk menghadapi Eclipsite.",
  ui_story_31530401_84_dialog_content = "Kombinasi cemerlang antara pendidikan dan hiburan, ditambah itu akan meningkatkan keterampilan tempur setiap orang melawan Eclipsite.",
  ui_story_31530401_85_dialog_content = "Aku terkesan dengan visi jangka panjangmu!",
  ui_story_31530401_86_dialog_content = "Benarkah? Ha... Ha...",
  ui_story_31530401_87_dialog_content = "Dan varian mawar yang indah ini secara mengejutkan Jola sedang dibudidayakan...",
  ui_story_31530401_88_dialog_content = "Duri mereka sebenarnya ratusan kali lebih tajam dari mawar biasa.",
  ui_story_31530401_89_dialog_content = "Jika mereka bisa ditanam di garis depan, mereka akan efektif memperlambat kecepatan Eclipsite yang mendekat.",
  ui_story_31530401_90_dialog_content = "(Mengapa saya tidak memikirkan itu?)",
  ui_story_31530401_91_dialog_content = "(Meskipun ini akan menjadi takdir yang kejam bagi bunga-bunga indah ini...)",
  ui_story_31530401_92_dialog_content = "(Tapi ini berarti aku akhirnya memiliki rencana riset yang layak untuk diajukan!)",
  ui_story_31530401_93_dialog_content = "Saya hanya seorang prajurit.",
  ui_story_31530401_94_dialog_content = "Saya sangat terharu oleh inovasi dan kreativitas dari risetmu.",
  ui_story_31530401_95_dialog_content = "Penelitian ilmiah seperti mendaki gunung, selalu berusaha mencapai puncaknya meskipun menghadapi banyak rintangan.",
  ui_story_31530401_96_dialog_content = "Di seluruh waktu, peneliti telah menjadi jantung dari Illumina Federation. Tanpa kalian semua...",
  ui_story_31530401_97_dialog_content = "Tak akan ada makanan apa pun bagi orang Illumina, tidak juga akan ada sepucuk senjata pun di tangan prajurit Illumina.",
  ui_story_31530401_98_dialog_content = "Jangan ragu-ragu saat meminta pendanaan riset tahun depan! Aku akan mendukungnya sepenuhnya!",
  ui_story_31530401_99_dialog_content = "Grand Marshal, saya akan segera mengembangkan spesies mawar tempur baru!",
  ui_story_31530401_100_dialog_content = "Jika ide tentang game tempur Eclipsite dapat terwujud, artinya kita dapat berkompetisi dengan lebih banyak orang secara real time, 'kan?",
  ui_story_31530401_101_dialog_content = "Hal-hal makin menarik. Aku akan mempercepatnya...",
  ui_story_31530401_102_dialog_content = "Kita juga akan membuat catatan riset kami tentang Komandan Hiiro lebih mendalam!",
  ui_story_31530401_103_dialog_content = "Hah? Ah... A-Aku juga... aku juga... melakukan sejumlah eksperimen...",
  ui_story_31530401_104_dialog_content = "(Setiap orang tampaknya terpuruk karena hasil penelitian mereka, tetapi sekarang ada semangat juang yang baru di mata mereka...)",
  ui_story_31530401_105_dialog_content = "(Apakah ini... keajaiban Reinhardt?)",
  ui_story_31530401_106_dialog_content = "Haruskah kita juga pergi sekarang?",
  ui_story_31530401_107_dialog_content = "Hah?",
  ui_story_31530401_108_dialog_content = "Ke tempat berikutnya!",
  ui_story_31530401_109_dialog_content = "<color=#e8d9bb>Illumina: Garis Depan</color>",
  ui_story_31530401_110_dialog_content = "Hiiro, aku akan memimpin tim ke depan untuk menggali parit pertahanan.",
  ui_story_31530401_111_dialog_content = "Tim lain akan mengikuti rencana awalmu!",
  ui_story_31530401_112_dialog_content = "Baik, Grand Marshal!",
  ui_story_31530401_113_dialog_content = "PlayerName, ambil sekop dan ikuti aku.",
  ui_story_31530401_114_dialog_content = "Hah? Kita ke garis depan untuk menggali parit?",
  ui_story_31530401_115_dialog_content = "Apakah semua ini benar-benar terjadi dalam satu hari...?",
  ui_story_31530401_116_dialog_content = "Rekan-rekan Illumina! Perang adalah hal kejam, dan wajar kalau kita takut menghadapi pertempuran.",
  ui_story_31530401_117_dialog_content = "Pertempuran yang baru saja berakhir adalah kemenangan besar bagi kita.",
  ui_story_31530401_118_dialog_content = "Setiap orang berhasil mengatasi ketakutan mereka dan bertahan hingga akhir.",
  ui_story_31530401_119_dialog_content = "Setiap dari kalian adalah pahlawan. Kalian adalah kebanggaan Illumina!",
  ui_story_31530401_120_dialog_content = "Namun, kemenangan akhir belum kita raih.",
  ui_story_31530401_122_dialog_content = "Parit pertahanan baru menunggu untuk kita gali! Medan pertempuran baru menunggu untuk kita tentukan!",
  ui_story_31530401_123_dialog_content = "Sekarang, mari kita lanjutkan untuk mempersembahkan diri kita pada pertempuran yang akan datang!",
  ui_story_31530401_124_dialog_content = "Grand Marshal! Grand Marshal! Grand Marshal!",
  ui_story_31530401_125_dialog_content = "(Mata para prajurit yang sempat meredup dan kehilangan semangat akibat serangan sebelumnya kini kembali menyala.)",
  ui_story_31530401_126_dialog_content = "(Reinhardt...)",
  ui_story_31530401_127_dialog_content = "Ayo kita pergi!",
  ui_story_31530401_128_dialog_content = "Maju!",
  ui_story_31530401_129_dialog_content = "Maju!",
  ui_story_31530401_130_dialog_content = "<color=#e8d9bb>Kota Gannon, Distrik Administratif</color>",
  ui_story_31530401_131_dialog_content = "M-Maju...",
  ui_story_31530401_132_dialog_content = "Hahaha, kita tidak di garis depan lagi. Kau berencana untuk ditugaskan di barisan mana?",
  ui_story_31530401_133_dialog_content = "Oh, b-benar.",
  ui_story_31530401_134_dialog_content = "... Maaf, mungkin aku belum kembali ke kesadaranku.",
  ui_story_31530401_135_dialog_content = "Duduk di sini dan istirahatlah sebentar. Kamu dapat meringkas semua catatan hari ini sembari istirahat.",
  ui_story_31530401_136_dialog_content = "Aku akan pergi ke ruang konferensi untuk rapat. Mestinya hanya sebentar.",
  ui_story_31530401_137_dialog_content = "B-baiklah!",
  ui_story_31530401_138_dialog_content = "(Sebelumnya Reinhardt menggali parit pertahanan bersama prajurit berjam-jam...)",
  ui_story_31530401_139_dialog_content = "(Bahkan mereka telah menggali dua kali lebih panjang dari perkiraan!)",
  ui_story_31530401_140_dialog_content = "(Aduh... Aku tak bisa lagi meski begitu. Ini terlalu berat untuk tubuhku...!)",
  ui_story_31530401_141_dialog_content = "*Mendengkur*",
  ui_story_31530401_142_dialog_content = "PlayerName?",
  ui_story_31530401_143_dialog_content = "Berhenti melamun dan masuklah, sini ikut rapat.",
  ui_story_31530401_144_dialog_content = "Rapat? Apakah aku harus ikut juga? S-Siapa lagi yang menghadiri?",
  ui_story_31530401_145_dialog_content = "Hahaha, kau akan tahu saat masuk.",
  ui_story_31530401_146_dialog_content = "Oh...",
  ui_story_31530401_147_dialog_content = "PlayerName, kamu belum menyelesaikan lari 100 km. Mengapa kamu sudah mau pergi?",
  ui_story_31530401_148_dialog_content = "Ck, PlayerName, mengapa tidak berlatih di bawah pengawasanku? Latihanku tidak kalah intens dari Sharona, kok!",
  ui_story_31530401_149_dialog_content = "Uh oh, Eclipsite telah menembus garis depan... PlayerName, kirimkan bantuan!",
  ui_story_31530401_150_dialog_content = "Jangan pergi, PlayerName.",
  ui_story_31530401_151_dialog_content = "Coba game penghubung superstrategisku untuk mengalahkan Eclipsite pertama!",
  ui_story_31530401_152_dialog_content = "Satu per satu, semuanya...",
  ui_story_31530401_153_dialog_content = "Satu per satu...",
  ui_story_31530401_154_dialog_content = "<color=#e8d9bb>Brak!</color>",
  ui_story_31530401_155_dialog_content = "*Mendengkur*",
  ui_story_31530401_156_dialog_content = "(Itu menakutkan. Ternyata hanya mimpi...)",
  ui_story_31530401_157_dialog_content = "Akhirnya, kamu bangun.",
  ui_story_31530401_158_dialog_content = "(Hah? Rapat Reinhardt sudah selesai?)",
  ui_story_31530401_159_dialog_content = "(Tapi dia... Kenapa dia tampak begitu marah?)",
  ui_story_31530401_160_dialog_content = "(Oh tidak... Dia memintaku membuat ringkasan dari catatanku, tetapi aku tertidur tanpa menulis satu kata pun...)",
  ui_story_31530401_161_dialog_content = "(Reinhardt pasti marah karena hal ini...)",
  ui_story_31530401_162_dialog_content = "(Aku harus apa sekarang? Tolong aku, kumohon...)",
  ui_story_31530401_163_dialog_content = "<color=#e8d9bb>*perut keroncongan*</color>",
  ui_story_31530401_164_dialog_content = "Hah? Tadi itu...",
  ui_story_31530401_165_dialog_content = "Ehem. Maaf, sepertinya perutku keroncongan.",
  ui_story_31530401_166_dialog_content = "Masih ada waktu, kok. Ayo, kita ke kantin!",
  ui_story_31530401_167_dialog_content = "Baiklah…",
  ui_story_31530401_168_dialog_content = "(Mengapa dia begitu diam? Dia pasti masih marah.)",
  ui_story_31530401_169_dialog_content = "(Suasananya sangat canggung...)",
  ui_story_31530401_170_dialog_content = "Um... Maafkan aku!",
  ui_story_31530401_171_dialog_content = "Hah? Mengapa kau meminta maaf?",
  ui_story_31530401_172_dialog_content = "Aku terlalu lelah lebih awal... sehingga aku tidak dapat menyelesaikan ringkasan hari ini...",
  ui_story_31530401_173_dialog_content = "Tolong jangan marah... Aku akan mencari waktu untuk menyelesaikannya!",
  ui_story_31530401_174_dialog_content = "Aku? Marah?",
  ui_story_31530401_175_dialog_content = "Hahahaha, maaf, maaf! Aku memang selalu cemberut kalau lapar.",
  ui_story_31530401_176_dialog_content = "Vivian sudah lama sekali menegurku tentang hal ini, tetapi aku belum bisa meninggalkan kebiasaan itu.",
  ui_story_31530401_177_dialog_content = "Oh, begitu rupanya.",
  ui_story_31530401_178_option_content = "Wah, syukurlah.",
  ui_story_31530401_179_dialog_content = "Hmm? Kau senang kalau aku memelihara tabiat buruk ini?",
  ui_story_31530401_180_dialog_content = "Itu... Maaf, bukan! Bukan itu maksudku!",
  ui_story_31530401_181_dialog_content = "Tapi, menurutku, itu bukan benar-benar kebiasaan buruk.",
  ui_story_31530401_182_option_content = "Apa kebiasaan menarik itu.",
  ui_story_31530401_183_dialog_content = "Rasanya Grand Marshal yang selalu sempurna itu sekarang tampak sedikit lebih dekat dengan kami yang normal ini.",
  ui_story_31530401_184_dialog_content = "Selalu sempurna? Saya tidak akan mengatakan itu tentang diri saya.",
  ui_story_31530401_185_dialog_content = "Bagaimana tidak? Dalam sehari ini saja kau menyelesaikan pekerjaan yang baru bisa kuselesaikan dalam sebulan!",
  ui_story_31530401_186_dialog_content = "Dan setiap tugas ditangani dengan sempurna, tanpa cacat.",
  ui_story_31530401_187_dialog_content = "Tak heran jika orang-orang Illumina sangat memuja Grand Marshal.",
  ui_story_31530401_188_dialog_content = "Aku melihatnya sendiri hari ini. Kau pasti tahu semacam sihir untuk memanipulasi pikiran orang!",
  ui_story_31530401_189_dialog_content = "Hahahaha, PlayerName, kau memiliki imajinasi yang cukup!",
  ui_story_31530401_190_dialog_content = "Pekerjaan anggota baru adalah berlatih, sementara pekerjaan peneliti adalah melakukan eksperimen...",
  ui_story_31530401_191_dialog_content = "Dan tugas Grand Marshal adalah merencanakan strategi langkah ke depan saat orang-orang kehilangan arah.",
  ui_story_31530401_192_dialog_content = "Jika kau terus menganggap aku punya semacam kemampuan magis, aku hanya bisa bilang—",
  ui_story_31530401_193_dialog_content = "Kita sama, dong!",
  ui_story_31530401_194_dialog_content = "Hah?",
  ui_story_31530401_195_dialog_content = "Caelestite terakhir yang legendaris ini kekurangan kekuatan fisik dan, tidak ada kata yang lebih baik, rapuh.",
  ui_story_31530401_196_dialog_content = "Namun, kamu mampu membuat begitu banyak orang bergabung dalam petualanganmu.",
  ui_story_31530401_197_dialog_content = "Bahkan anak buah Vivian, Vice, mau mengikutimu saat kau mengembara ke seluruh dunia.",
  ui_story_31530401_198_dialog_content = "Apakah kau juga menggunakan sihir untuk memikat orang mendekatimu?",
  ui_story_31530401_199_dialog_content = "Itu…?",
  ui_story_31530401_200_dialog_content = "<color=#e8d9bb>*perut keroncongan*</color>",
  ui_story_31530401_201_dialog_content = "Hahaha! Sepertinya perutmu juga mulai keroncongan, ya?",
  ui_story_31530401_202_dialog_content = "Ayo, mari puaskan mereka terlebih dahulu.",
  ui_story_31530401_203_dialog_content = "Setelah itu, kita akan kembali dan menyelesaikan sisa laporan, dan melanjutkan percakapan ini setelahnya!",
  ui_story_31530401_204_dialog_content = "(Kita akan terus bekerja?!)",
  ui_story_31530401_205_dialog_content = "(Kapan hari ini akan berakhir...)",
  ui_story_31530401_206_dialog_content = "(Reinhardt bukan Grand Marshal, saya cukup yakin dia semacam makhluk yang tak pernah habis.)",
  ui_story_31530401_207_dialog_content = "Wuu-huu!",
  ui_story_31530401_208_dialog_content = "Enak! Pot roast memang juara!",
  ui_story_31530401_209_dialog_content = "Satu porsi lagi, tolong!",
  ui_story_31530601_1_dialog_content = "Apakah pemuda itu Caelestite legendaris?",
  ui_story_31530601_2_dialog_content = "Tidak mungkin, penampilannya terlalu kumal untuk menjadi legenda apapun.",
  ui_story_31530601_3_dialog_content = "Setiap orang memiliki selera mereka sendiri. Mungkin dia hanya lebih suka terlihat seperti ini?",
  ui_story_31530601_4_dialog_content = "Tapi sebagai satu-satunya yang selamat dari seluruh ras, dia pasti mewarisi semacam kekayaan, bukan? Dia bahkan memiliki semua Eraveil—",
  ui_story_31530601_5_dialog_content = "(Mereka telah menatapku selama ini... Dan sekarang mereka mulai mengatakan beberapa hal yang benar-benar liar.)",
  ui_story_31530601_6_dialog_content = "(Apakah ini benar-benar tempat yang tepat? Kenapa dia mengundangku ke perjamuan mewah seperti ini...?)",
  ui_story_31530601_7_dialog_content = "\"Halo, PlayerName,\"",
  ui_story_31530601_8_dialog_content = "\"Jika Anda memiliki waktu, bisakah Anda datang ke Umbraton? Alamatnya adalah #XXX di Jalan XXXX. P.S. Meskipun Anda tidak memiliki waktu, tolong berusaha sebaik mungkin untuk datang.\"",
  ui_story_31530601_9_dialog_content = "Maaf, tapi apakah Anda perwakilan dari Eraveil?",
  ui_story_31530601_10_dialog_content = "Hah?!",
  ui_story_31530601_11_dialog_content = "Aku mengenalmu. Kau adalah Caelestite terakhir, mewarisi kekuatan paling jahat dari rasmu.",
  ui_story_31530601_12_dialog_content = "Anda mengendalikan pikiran setiap makhluk hidup di Astra! Dengan satu keinginan saja, Anda bisa mengubah setiap orang di ruangan ini menjadi boneka Anda!",
  ui_story_31530601_13_dialog_content = "Sekarang tunggu sebentar saja!",
  ui_story_31530601_14_dialog_content = "Mengubah kita menjadi boneka, katamu? Maaf, tetapi kekayaan dan status sudah lebih dari cukup untuk melakukan itu. Jangan pedulikan orang-orang ini, temanku; kamu akan menemukan bahwa beberapa bangsawan lebih unggul dari yang lain.",
  ui_story_31530601_15_dialog_content = "Tidak ada yang ingin berteman dengan kotoran, tetapi saya dapat membantu Anda dalam hal itu.",
  ui_story_31530601_16_dialog_content = "A-Aku bisa menjaga diriku sendiri, terima kasih...",
  ui_story_31530601_17_dialog_content = "Apa? Si Caelestite? Di mana?! Biarkan aku melihat, biarkan aku melihat—",
  ui_story_31530601_18_dialog_content = "—Hadirin sekalian.",
  ui_story_31530601_19_dialog_content = "(Suara itu...!)",
  ui_story_31530601_20_dialog_content = "Mendekatinya sangat diterima, tetapi saya meminta Anda untuk bersikap sedikit lebih bermartabat.",
  ui_story_31530601_21_dialog_content = "Jika tidak ada alasan lain, setidaknya lakukanlah demi saya. Lagi pula—",
  ui_story_31530601_22_dialog_content = "PlayerName ada di sini atas permintaanku.",
  ui_story_31530601_23_dialog_content = "Reinhardt...! Kamu benar-benar di sini!",
  ui_story_31530601_24_dialog_content = "(Dan dengan pakaian formal seperti itu juga...)",
  ui_story_31530601_25_dialog_content = "Grand Marshal Illumina! Dia mengundang Caelestite...",
  ui_story_31530601_26_dialog_content = "Dan Caelestite memanggilnya dengan namanya...",
  ui_story_31530601_27_dialog_content = "Tuan PlayerName, Anda harus datang ke pesta berikutnya dari keluarga kami!",
  ui_story_31530601_28_dialog_content = "Kami akan merasa terhormat jika kamu menjadi tamu kami!",
  ui_story_31530601_29_dialog_content = "Sebelah sini, PlayerName.",
  ui_story_31530601_30_dialog_content = "(... aku selamat!)",
  ui_story_31530601_31_dialog_content = "<color=#e8d9bb>Kerumunan secara instingtif berpisah, dan semua mata tertuju pada setiap langkah mereka saat mereka menaiki tangga.</color>",
  ui_story_31530601_32_dialog_content = "... Maaf soal itu. Saya sedang dalam pertemuan penting, dan saya tidak bisa meninggalkannya tepat waktu untuk menyelamatkan Anda dari orang-orang itu.",
  ui_story_31530601_33_dialog_content = "Jangan khawatir tentang itu! Jika bukan karena itu, saya tidak akan pernah tahu betapa konyolnya rumor tentang saya telah menyebar.",
  ui_story_31530601_34_dialog_content = "Ternyata, aku adalah penjahat kaya yang mampu memperbudak setiap pikiran di Astra... Setelah hari ini, aku tidak akan heran jika mereka mulai menuduh Illumina bersekongkol dengan Eraveil!",
  ui_story_31530601_35_dialog_content = "Hahaha, jadi tampaknya aku khawatir untuk tidak ada alasan! Bagus, aku suka melihat sisi <color=#FFB400>bebas dan nakal</color> darimu.",
  ui_story_31530601_36_dialog_content = "Aku tidak yakin itu pujian atau bukan...",
  ui_story_31530601_37_dialog_content = "Kamu sangat berbeda dari biasanya hari ini. Saya kesulitan membaca pikiranmu sekarang.",
  ui_story_31530601_38_dialog_content = "Berbeda? Apakah kamu bilang aku lebih keren dari biasanya?",
  ui_story_31530601_39_dialog_content = "Aku baru saja ingin mengatakan itu! Tapi... ya, kekhasan dan kehadiranmu terasa sangat berbeda, semacam—",
  ui_story_31530601_40_dialog_content = "Kamu akan mengatakan sesuatu yang keras, \"Tidak buruk, sekarang mulai membuat senjata-senjata ini!\" atau \"Aku ingin profilnya di meja saya dalam sepuluh menit.\"",
  ui_story_31530601_41_dialog_content = "... Saya rasa Grand Marshal di Illumina tidak seharusnya terlihat seperti itu di mata siapa pun!",
  ui_story_31530601_42_dialog_content = "Tapi begitulah rasanya saat kamu menyelamatkanku dari kerumunan... Sungguh keren!",
  ui_story_31530601_43_dialog_content = "Orang-orang itu sama sekali tidak seperti kamu. Yang mereka pedulikan hanyalah kepentingan mereka sendiri... Tapi itu tidak apa-apa, karena dunia masih membutuhkan orang-orang seperti mereka.",
  ui_story_31530601_44_dialog_content = "Aku akan menangani mereka, jadi silakan hidup bebas dan sesuka hatimu.",
  ui_story_31530601_45_dialog_content = "Itu adalah sesuatu yang hanya bisa kamu lakukan.",
  ui_story_31530601_46_dialog_content = "Hanya aku...?",
  ui_story_31530601_47_dialog_content = "Saya terkejut mengetahui bahwa Reinhardt telah mengundang tamu malam ini—tapi mengingat itu PlayerName, saya benar-benar mengerti.",
  ui_story_31530601_48_dialog_content = "Shadowlord...!",
  ui_story_31530601_49_dialog_content = "(Jadi, rapat penting itu antara dia dan Reinhardt?)",
  ui_story_31530601_50_dialog_content = "Menjadi Shadowlord pasti melelahkan pada saat-saat tertentu. Prajurit Illumina pada umumnya jujur dan sederhana, yang membuat berurusan dengan mereka cukup mudah. Kamu, di sisi lain, harus berurusan dengan orang-orang di lantai bawah.",
  ui_story_31530601_51_dialog_content = "Menurut pendapat saya, menginspirasi dan memimpin massa yang jujur dan sederhana adalah pekerjaan yang jauh lebih menakutkan.",
  ui_story_31530601_52_dialog_content = "Negosiasi hari ini pasti tidak mungkin tanpa kehadiran Anda.",
  ui_story_31530601_53_dialog_content = "Aku hanya bisa melakukan sepertiga dari pekerjaan, jadi aku akan memberikan yang terbaik.",
  ui_story_31530601_54_dialog_content = "Sisanya terserah kamu dan Lady Carleen.",
  ui_story_31530601_55_dialog_content = "(Carleen juga ada di sana?! Aku ingin tahu di mana dia sekarang...?)",
  ui_story_31530601_56_dialog_content = "Marsekal Agung Reinhardt! Dan PlayerName, teman baikku!",
  ui_story_31530601_57_dialog_content = "(Kapan kita menjadi teman?!)",
  ui_story_31530601_58_dialog_content = "Apakah kamu ingin bergabung dengan teman-teman saya dan saya untuk obrolan singkat? Mereka adalah bangsawan dari Lumopolis, tahu, dan—",
  ui_story_31530601_59_dialog_content = "Apa yang baru saja kamu katakan, PlayerName? Bahwa Eclipsite telah menyusup ke Colossus? Jangan khawatir, aku akan membantu kamu mengusir mereka!",
  ui_story_31530601_60_dialog_content = "Hah?! Ah... It-Itu benar! Banyak sekali Eclipsite! Vice telah mempertahankan diri dari mereka selama tiga hari sekarang! Kami sangat membutuhkan bantuanmu!",
  ui_story_31530601_61_dialog_content = "Seperti yang bisa Anda lihat, pria baik-baik, teman kita sangat membutuhkan bantuan. Jika Anda berkenan memaafkan kami, kami harus pergi.",
  ui_story_31530601_62_dialog_content = "Harap berhati-hati. Saya akan pastikan untuk memberi tahu Lady Carleen tentang situasi Anda.",
  ui_story_31530601_63_dialog_content = "Ah, kembali di Kota Gannon!",
  ui_story_31530601_64_dialog_content = "Dulu aku berpikir tempat ini begitu sempit dan menyesakkan, tapi setelah pesta itu, setiap hembusan udara terasa begitu menyegarkan!",
  ui_story_31530601_65_dialog_content = "...",
  ui_story_31530601_66_dialog_content = "(... Ups! Seharusnya aku tidak mengatakan itu dengan keras!)",
  ui_story_31530601_67_dialog_content = "Jangan khawatir, aku tidak akan marah tentang apa yang kamu katakan tentang Gannon City.",
  ui_story_31530601_68_dialog_content = "Dia melihat menembus diriku!",
  ui_story_31530601_69_dialog_content = "Lagipula, untuk seseorang yang bebas seperti dirimu, tempat ini pasti akan terasa sempit dan pengap.",
  ui_story_31530601_70_dialog_content = "Tidak seorang pun... seharusnya pernah terbiasa hidup seperti ini.",
  ui_story_31530601_71_dialog_content = "... Bolehkah aku bertanya mengapa kamu mengundangku ke pesta itu di Umbraton hari ini? Atau mengapa kamu memintaku untuk membawamu kembali ke Kota Gannon sebelum acara itu selesai?",
  ui_story_31530601_72_dialog_content = "B-Bukan kah kamu berencana menggunakan saya sebagai alasan untuk pergi, kan?",
  ui_story_31530601_73_dialog_content = "Kamu adalah temanku yang terkasih dan sekutu yang dapat diandalkan. Kenapa aku harus mengolok-olokmu seperti itu?",
  ui_story_31530601_74_dialog_content = "Alasan aku memintamu datang adalah... Awas!",
  ui_story_31530601_75_dialog_content = "(Hampir saja... Nyaris saja aku tertabrak kendaraan angkutan itu! Seharusnya aku lebih memperhatikan sekitarku...)",
  ui_story_31530601_76_dialog_content = "Perhatikan kemana kamu pergi. Sektor terbaru Gannon tidak memerlukan korban hidup.",
  ui_story_31530601_77_dialog_content = "A-aku minta maaf! Tunggu, sektor terbaru? Apakah kalian sedang mengembangkan area baru?",
  ui_story_31530601_78_dialog_content = "Sekarang kamu sebutkan itu... kendaraan pengangkut itu membawa banyak tanaman, bukan? Saya tidak berpikir saya pernah melihat satu tanaman pun di Kota Gannon sebelumnya.",
  ui_story_31530601_79_dialog_content = "Heheh.",
  ui_story_31530601_80_dialog_content = "... Apakah aku benar-benar berkhayal?! Tawa itu hampir terdengar seperti kamu merasa puas dengan dirimu sendiri!",
  ui_story_31530601_81_dialog_content = "Kamu akan tahu setelah melihatnya sendiri. Ayo ikut denganku!",
  ui_story_31530601_82_dialog_content = "I-Ini masih... Kota Gannon?",
  ui_story_31530601_83_dialog_content = "Sulit dipercaya…",
  ui_story_31530601_84_dialog_content = "Saya dapat menjamin kepada kamu bahwa ini masih Kota Gannon. Selamat datang di sektor perumahan terbaru kami.",
  ui_story_31530601_85_dialog_content = "Ketika kami merancang tempat ini, kami ingin itu menjadi sesuatu yang bahkan Caelestite yang bebas dan liar sekalipun akan kagumi.",
  ui_story_31530601_86_dialog_content = "Saya? Tapi kenapa? Bukan untuk mencari alasan atas kekurangan saya atau apa pun, tetapi di dunia ini ada banyak orang lain yang bebas dan tidak teratur.",
  ui_story_31530601_87_dialog_content = "Saya sama sekali tidak melihat itu sebagai kekurangan.",
  ui_story_31530601_88_dialog_content = "Kamu terbiasa hidup di dunia yang luas terbuka, dan menikmati rasa kemandirian yang memungkinkanmu melihat segala yang ditawarkannya—",
  ui_story_31530601_89_dialog_content = "Itulah artinya bebas dan tidak teratur. Bukan kekurangan; itu adalah bentuk kebahagiaan langka yang hanya sedikit orang yang akan pernah mengalaminya.",
  ui_story_31530601_90_dialog_content = "Dan kebahagiaan itu adalah sesuatu yang ingin saya berikan untuk setiap orang di Illumina.",
  ui_story_31530601_91_dialog_content = "!!!",
  ui_story_31530601_92_dialog_content = "Selama berabad-abad, orang-orang Illumina telah hidup secara hemat di bawah tanah, semua dalam persiapan untuk perang yang tak pernah berakhir.",
  ui_story_31530601_93_dialog_content = "Kita tidak punya pilihan selain hidup seperti ini, tapi itu tidak berarti kita tidak pantas mendapatkan yang lebih baik.",
  ui_story_31530601_94_dialog_content = "Inilah mengapa saya mengusulkan rencana baru untuk meningkatkan kehidupan warga kita. Sektor terbaru ini adalah lokasi uji coba untuk rencana ini.",
  ui_story_31530601_95_dialog_content = "PlayerName, bisakah kamu membantuku?",
  ui_story_31530601_96_dialog_content = "Sebagai sekutu Illumina, dan orang paling bebas di dunia—",
  ui_story_31530601_97_dialog_content = "Tolong berikan saya evaluasi jujur tentang sektor terbaru kami. Wawasan Anda adalah sesuatu yang sangat saya hargai.",
  ui_story_31530601_98_dialog_content = "Reinhardt... Saya terkejut bahwa kamu bisa menciptakan sesuatu yang begitu luar biasa!",
  ui_story_31530601_99_dialog_content = "Tentu saja aku akan membantu kamu! T-Tapi aku tidak yakin bagaimana cara menilai tempat ini...",
  ui_story_31530601_100_dialog_content = "Ini sederhana. Berikan saja pendapat paling jujur Anda tentang itu.",
  ui_story_31530601_101_dialog_content = "Tunggu! Di seberang jalan... Apakah itu penjual otomatis?",
  ui_story_31530601_102_dialog_content = "Aku dengar kamu dan teman-temanmu menemukan sesuatu seperti ini di Undercity kuno. Itu menarik rasa penasaranku, jadi aku menyuruh Gronru merakit model tes.",
  ui_story_31530601_103_dialog_content = "Yah? Apakah ini mirip dengan yang asli?",
  ui_story_31530601_104_dialog_content = "Mari kita cari tahu. Tolong berikan satu bar sarapan...",
  ui_story_31530601_105_dialog_content = "Benar-benar keluar!",
  ui_story_31530601_106_dialog_content = "Ini luar biasa! Makanan selalu dirasionalkan di Kota Gannon, tetapi sekarang bisa disajikan sesuai permintaan...",
  ui_story_31530601_107_dialog_content = "Ini hanya masalah biasa. Sekarang bahwa sumber daya kita cukup melimpah untuk menopang kita, aksesibilitas dan kenyamanan menjadi prioritas selanjutnya. Lagipula, tidak ada yang suka mengantri untuk sesuatu.",
  ui_story_31530601_108_dialog_content = "Mari kita lanjutkan ke jalan berikutnya.",
  ui_story_31530601_109_dialog_content = "Taman yang tampak indah! Saya belum pernah melihat sesuatu yang begitu hijau di Kota Gannon sebelumnya...",
  ui_story_31530601_110_dialog_content = "Migard mengklaim bahwa semua tanaman ini mampu tumbuh dengan baik di bawah pencahayaan buatan.",
  ui_story_31530601_111_dialog_content = "Saya juga menjaga dua di kamar saya. Jika seseorang seperti saya bisa menjaga mereka tetap hidup, maka sisanya di Gannon City seharusnya tidak memiliki masalah melakukan hal yang sama!",
  ui_story_31530601_112_dialog_content = "Dan semua platform melompat dan peralatan latihan ini... Apakah mereka untuk berolahraga?",
  ui_story_31530601_113_dialog_content = "Mata yang baik. Bahkan, saya bangga menyebut ini sebagai beberapa karya terbaik saya.",
  ui_story_31530601_114_dialog_content = "Bahkan seseorang yang menghindari olahraga mungkin akan tergoda untuk mencoba ini. Kamu tidak setuju?",
  ui_story_31530601_115_dialog_content = "Ayo, kamu harus mencobanya. Aku akan membantumu!",
  ui_story_31530601_116_dialog_content = "A-Aku baik-baik saja, tapi... Aku bisa merasakan tempat ini telah berubah. Aku bahkan bisa menggambarkannya sebagai \"hidup\" sekarang...",
  ui_story_31530601_117_dialog_content = "... Tunggu, aku mengerti sekarang! Kau pergi ke pesta itu di Umbraton demi sektor baru ini, 'kan?",
  ui_story_31530601_118_dialog_content = "Benar! Illumina telah menjadi terlalu militer, sehingga beberapa kebutuhan sehari-hari menjadi langka.",
  ui_story_31530601_119_dialog_content = "Jika kita benar-benar ingin berkembang, kita akan membutuhkan dukungan dari Umbraton dan Lumopolis.",
  ui_story_31530601_120_dialog_content = "Kamu tidak ingin bar makanan menjadi satu-satunya hal di penjual otomatis kami, bukan?",
  ui_story_31530601_121_dialog_content = "Jadi itu sebabnya kamu bertemu dengan Carleen dan Istvan...",
  ui_story_31530601_122_dialog_content = "Sebuah proposal bisnis yang akan menguntungkan ketiga pihak—itu adalah kesepakatan yang kami capai saat itu.",
  ui_story_31530601_123_dialog_content = "Tapi tentu saja, sebuah persetujuan antara tiga pemimpin tidak akan cukup. Bangsawan, guild, geng... Yang paling penting adalah memiliki semua dari mereka di papan, juga.",
  ui_story_31530601_124_dialog_content = "Apakah itulah sebabnya semua orang kaya dan penting itu juga ada di sana?",
  ui_story_31530601_125_dialog_content = "Tentu saja. Lagipula, siapa di antara mereka yang bisa melewatkan peluang bisnis seperti ini? Sejujurnya, saya tidak terlalu pandai berurusan dengan mereka, sama seperti kamu.",
  ui_story_31530601_126_dialog_content = "Tapi, saya pasti akan memahaminya suatu hari nanti. Bahkan pedagang paling licik pun tidak ada apa-apanya dibandingkan dengan orang-orang tua yang keras kepala yang harus saya hadapi setiap hari.",
  ui_story_31530601_127_dialog_content = "Tegas, cakap, dan penuh taktik... Itulah Grand Marshal dari Illumina.",
  ui_story_31530601_128_dialog_content = "Tapi, itu banyak sekali untuk ditangani sendirian... Apa kamu tidak akan merasa lelah?",
  ui_story_31530601_129_dialog_content = "Saya hampir tidak berpikir demikian. Lagipula, saya bukanlah orang yang mengemudikan kendaraan transportasi atau merawat tanaman.",
  ui_story_31530601_130_dialog_content = "Itu tidak berarti piringmu tidak penuh. Kamu menyebutkan Gronru dan Migard, serta tempat ini memiliki \"beberapa karya terbaikmu\"...",
  ui_story_31530601_131_dialog_content = "Tidak ada gunanya menyangkalnya. Anda terlibat dalam hampir setiap aspek pengembangan sektor baru!",
  ui_story_31530601_132_dialog_content = "A-Ahem... Penting untuk memantau setiap langkah dalam proses seperti ini... Lagipula, saya tidak mencari pujian pribadi di sini.",
  ui_story_31530601_133_dialog_content = "Saya meminta pendapat jujur Anda tentang tempat ini.",
  ui_story_31530601_134_dialog_content = "Jangan lihat saya sebagai Grand Marshal, tetapi sebagai teman dan kawan seperjuangan lainnya, dan katakan persis apa yang kamu rasakan tentang itu. Bahkan kritik keras sepenuhnya baik-baik saja!",
  ui_story_31530601_135_option_content = "Saya benar-benar berpikir sektor baru ini luar biasa.",
  ui_story_31530601_136_dialog_content = "Sangat tenang dan damai. Bahkan seseorang yang serius seperti kamu merasa cukup santai untuk mengobrol sebanyak ini dengan saya di sini. Bukankah itu tujuannya?",
  ui_story_31530601_137_dialog_content = "Kamu pikir... Aku merasa santai?",
  ui_story_31530601_138_option_content = "Saya pikir kamu terlalu menuntut diri sendiri.",
  ui_story_31530601_139_dialog_content = "Setelah mendengar kamu berbicara tentang sektor baru, bisa kulihat bahwa kamu telah memberikan banyak hal untuk tempat ini. Kau terdengar sangat bahagia dan bangga, seolah-olah kamu sedang memperkenalkan sesuatu yang sangat kamu cintai.",
  ui_story_31530601_140_dialog_content = "Aku terdengar... bahagia?",
  ui_story_31530601_141_dialog_content = "Anda berarti Anda tidak menyadarinya?",
  ui_story_31530601_142_dialog_content = "Kamu baru saja menyebutkan begitu banyak hal tentang dirimu sendiri. Bagaimana kamu benci antri, atau bagaimana kamu tidak bisa merawat tanaman... Dan betapa bangganya kamu saat sesuatu selesai.",
  ui_story_31530601_143_dialog_content = "Haha… Hahahahaha!",
  ui_story_31530601_144_dialog_content = "Aku tahu mengundangmu ke sini adalah pilihan yang tepat!",
  ui_story_31530601_145_dialog_content = "Ah... Aku tidak bisa mengingat kapan terakhir kali aku tertawa sekeras ini.",
  ui_story_31530601_146_dialog_content = "Kurasa saat itu mereka masih ada...",
  ui_story_31530601_147_dialog_content = "Mereka? Maksudmu...",
  ui_story_31530601_148_dialog_content = "Adik perempuanku, serta Helios.",
  ui_story_31530601_149_dialog_content = "Kami dulu melakukan segalanya bersama. Belajar, berlatih, dan menjalani hidup kami.",
  ui_story_31530601_150_dialog_content = "Di waktu luang kami, kami juga akan datang ke tempat-tempat seperti ini dan menatap Kota Gannon dari tempat yang tinggi. Kami akan membicarakan segala macam hal yang tidak penting, tertawa sambil menikmati angin sepoi-sepoi.",
  ui_story_31530601_151_dialog_content = "Memikirkan kembali masa itu membuatku merasa sangat bernostalgia.",
  ui_story_31530601_152_dialog_content = "Reinhardt…",
  ui_story_31530601_153_dialog_content = "Tapi jangan khawatir. Tidak ada yang bisa tetap sama, dan meskipun beberapa perubahan bisa sangat membebani kita—",
  ui_story_31530601_154_dialog_content = "Lebih sering daripada tidak, perubahan itu menarik.",
  ui_story_31530601_155_dialog_content = "Lihat saja Kota Gannon: tempat yang sempit dan pengap berubah menjadi kota yang penuh semangat dan terbuka, bukan?",
  ui_story_31530601_156_dialog_content = "Dan menurut imajinasimu, bahkan aku tampak lebih santai dan banyak bicara sekarang.",
  ui_story_31530601_157_dialog_content = "Saya tidak membayangkan apa-apa!",
  ui_story_31530601_158_dialog_content = "Hehe. Kamu sendiri orang yang cukup luar biasa.",
  ui_story_31530601_159_dialog_content = "Setelah bertahun-tahun, kamu membantuku mengingat bagaimana rasanya berbincang dan tertawa bersama teman-temanku... Dan itu sudah lebih dari cukup untukku.",
  ui_story_31530601_160_dialog_content = "... Reinhardt?",
  ui_story_31530601_161_dialog_content = "Tapi Denier dan Helios tidak lagi bersamaku... Dan setelah hari ini, kamu akan kembali terbang ke seluruh dunia lagi.",
  ui_story_31530601_162_dialog_content = "Dan aku akan berada di sini, mengawasi seluruh Gannon City.",
  ui_story_31530601_163_dialog_content = "Aku akan menjadi saksi atas bangkitnya sektor baru ini, sebuah ruang hijau dan penuh kehidupan untuk dinikmati setiap orang.",
  ui_story_31530601_164_dialog_content = "Ini adalah tempat di mana orang-orang kita dapat hidup tanpa batasan dan memilih-milih makanan yang mereka inginkan.",
  ui_story_31530601_165_dialog_content = "Untuk warga Illumina, latihan bukan hanya tugas kami; itu juga hobi dan cara untuk tetap sehat.",
  ui_story_31530601_166_dialog_content = "Di sini, anak-anak bisa mendaki ke tempat tertinggi dan menghabiskan waktu berharga bersama teman-teman mereka, tertawa dan memandang kota seperti yang pernah kita lakukan. Tidak ada perang atau pertikaian yang akan mencapai mereka di sini.",
  ui_story_31530601_167_dialog_content = "Sebagai Grand Marshal dari Illumina Federation... Aku bersumpah untuk mengawasi segalanya.",
  ui_story_31530601_168_dialog_content = "Aku akan selalu di sini.",
  ui_story_31530601_169_dialog_content = "(Enlightened Illumination... Begitu, ya sekarang aku paham.)",
  ui_story_31530601_170_dialog_content = "(Tidak mungkin melihat orang ini hanya sebagai teman baik lainnya. Dia jauh lebih dari itu.)",
  ui_story_31530601_171_dialog_content = "Nah, temanku yang <color=#FFB400>bebas dan liar</color>... Karena kamu memiliki pendapat yang tinggi tentang tempat ini, mungkin kita bisa menukar sebidang tanah di Eraveil dengan sebuah lingkungan di sini? Bagaimana menurutmu?",
  ui_story_31530601_172_dialog_content = "Aku bisa membantumu mendaftar di militer kita dan bahkan memulaimu sebagai letnan!",
  ui_story_31530601_173_dialog_content = "... Kamu ingin saya memberikan rumah saya sebagai ganti bekerja di bawahmu? Apa yang terjadi dengan tidak mengolok-olok temanmu?!",
  ui_story_31530601_174_dialog_content = "Hahahahah!"
}
return config
